Bash(/tmp/search_keybind.ps1 << 'PSEOF'
Add-Type -AssemblyName System.IO.Compression.FileSystem

# Search for keybinding JARs
Write-Host "=== Searching for keybinding JARs ==="
$jars = Get-ChildItem -Recurse 'C:\\Users\\aaron\\Documents\\cradlemod\\.gradle\\loom-cache\\remapped_mods' -Filter '*.jar' | Where-Object { $_.Name -like '*keybind*' -or $_.Name -like '*key-binding*' }
foreach \($jar in $jars\) { Write-Host $jar.FullName }
if \(-not $jars\) { Write-Host "\(none found\)" }

# Search all Fabric API JARs for KeyBind/KeyMapping classes
Write-Host ""
Write-Host "=== Searching all Fabric JARs for KeyBind/KeyMapping ==="
$allJars = Get-ChildItem -Recurse 'C:\\Users\\aaron\\Documents\\cradlemod\\.gradle\\loom-cache\\remapped_mods' -Filter '*.jar'
foreach \($jar in $allJars\) {
    $zip = [System.IO.Compression.ZipFile]::OpenRead\($jar.FullName\)
    $entries = $zip.Entries | Where-Object { $_.FullName -like '*KeyBind*' -or $_.FullName -like '*KeyMapping*' }
    if \($entries.Count -gt 0\) {
        foreach \($e in $entries\) {
            Write-Host "$\($jar.Name\): $\($e.FullName\)"
        }
    }
    $zip.Dispose\(\)
}
Write-Host "DONE"
